package java.util.concurrent;
import java.util.*;
public class ConcurrentHashMap<K,V> extends AbstractMap<K,V> implements ConcurrentMap<K,V>, java.io.Serializable {
 private final HashMap<K,V> map;
 public ConcurrentHashMap(){map=new HashMap<K,V>();} public ConcurrentHashMap(int n){map=new HashMap<K,V>(n);} public ConcurrentHashMap(int n,float f){map=new HashMap<K,V>(n,f);} public ConcurrentHashMap(int n,float f,int concurrency){this(n,f);if(concurrency<=0)throw new IllegalArgumentException();} public ConcurrentHashMap(Map<? extends K,? extends V> m){this();putAll(m);}
 public int size(){return map.size();} public boolean isEmpty(){return map.isEmpty();} public boolean containsKey(Object k){if(k==null)throw new NullPointerException();return map.containsKey(k);} public boolean containsValue(Object v){if(v==null)throw new NullPointerException();return map.containsValue(v);} public boolean contains(Object v){return containsValue(v);} public V get(Object k){if(k==null)throw new NullPointerException();return map.get(k);} public V put(K k,V v){if(k==null||v==null)throw new NullPointerException();return map.put(k,v);} public V remove(Object k){if(k==null)throw new NullPointerException();return map.remove(k);} public void clear(){map.clear();} public Set<Entry<K,V>> entrySet(){return map.entrySet();}
 public synchronized V putIfAbsent(K k,V v){if(k==null||v==null)throw new NullPointerException();V old=map.get(k);if(old==null)map.put(k,v);return old;} public synchronized boolean remove(Object k,Object v){if(k==null)throw new NullPointerException();if(v==null)return false;V old=map.get(k);if(old!=null&&old.equals(v)){map.remove(k);return true;}return false;} public synchronized boolean replace(K k,V old,V value){if(k==null||old==null||value==null)throw new NullPointerException();V x=map.get(k);if(x!=null&&x.equals(old)){map.put(k,value);return true;}return false;} public synchronized V replace(K k,V v){if(k==null||v==null)throw new NullPointerException();return map.containsKey(k)?map.put(k,v):null;} public long mappingCount(){return size();}
}
